cat > vitest.smoke.config.mjs <<'EOF'
import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
export default defineConfig({
  plugins: [react()],
  test: { environment: 'node', server: { deps: { inline: [/@gravity-ui/, /\.css$/] } }, css: { include: [/.+/] } },
});
EOF
git stash list >/dev/null; cat > src/__smoke__.test.tsx <<'EOF'
import { describe, expect, it } from 'vitest';
import { renderToString } from 'react-dom/server';
import { App } from './App';
import { computeKpis } from './data/kpi';
import { generateOrders, REFERENCE_NOW } from './data/orders';

describe('smoke', () => {
  it('generates sorted, unique orders', () => {
    const orders = generateOrders();
    expect(orders).toHaveLength(240);
    expect(new Set(orders.map((o) => o.id)).size).toBe(240);
    for (let i = 1; i < orders.length; i++) {
      expect(orders[i - 1].createdAt.getTime()).toBeGreaterThanOrEqual(orders[i].createdAt.getTime());
    }
  });
  it('computes KPIs', () => {
    const kpis = computeKpis(generateOrders(), REFERENCE_NOW);
    console.log(JSON.stringify(kpis));
    expect(kpis.map((k) => k.id)).toEqual(['revenue', 'orders', 'average', 'cancels']);
  });
  it('server-renders the app shell', () => {
    const html = renderToString(<App />);
    expect(html).toContain('Главная');
    expect(html).toContain('Выручка за 30 дней');
    expect(html).toContain('Группировка:');
    expect(html).toContain('Клиент');
    console.log('html length', html.length);
  });
});
EOF
timeout 170 npx vitest run --config vitest.smoke.config.mjs src/__smoke__.test.tsx 2>&1 | grep -v "npm warn" | tail -60; rm -f src/__smoke__.test.tsx vitest.smoke.config.mjs; ls

