import { expect, it } from 'vitest';
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

it('server-renders the app shell inside ThemeProvider', () => {
  const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
  for (const s of ['Главная', 'Выручка за 30 дней', 'Группировка:', 'Клиент', 'Статус', 'Сумма', 'Пользователи', 'Настройки', 'Свернуть']) {
    expect(html, s).toContain(s);
  }
  console.log('rendered bytes', html.length);
});
EOF
